    [Fact]
    public void CanonicalGoldensAndIndependentHashes()
    {
        var commandBody=GraphParticipantReservationCodecsV2.Encode(CommandBody());var factBody=GraphParticipantReservationCodecsV2.Encode(FactBody());var(session,authority)=Authority();
        var commandOuter=GraphParticipantReservationCodecsV2.Encode(new GraphParticipantReservationCommandV2(session,authority,commandBody));var factOuter=GraphParticipantReservationCodecsV2.Encode(new GraphParticipantReservationFactV2(session,authority,factBody));
        var commandBodyHex=Convert.ToHexString(commandBody).ToLowerInvariant();var commandOuterHex=Convert.ToHexString(commandOuter).ToLowerInvariant();var factBodyHex=Convert.ToHexString(factBody).ToLowerInvariant();var factOuterHex=Convert.ToHexString(factOuter).ToLowerInvariant();
        Assert.Equal("",commandBodyHex);
        Assert.Equal("",commandOuterHex);
        Assert.Equal("",factBodyHex);
        Assert.Equal("",factOuterHex);
        Assert.Equal("4cbae9abb04d249f43e1ef0ffd9e854a6a37e842b999d050e4f6f431f651075d",AuthorityPayloadHashV1.Compute(GraphParticipantReservationPayloadRegistrationsV2.ReservationCommand.SchemaToken,GraphParticipantReservationPayloadRegistrationsV2.ReservationCommand.Schema,commandOuter).ToString().Replace("sha256:",string.Empty,StringComparison.Ordinal));
        Assert.Equal("0eaba245940d335307244ccab94ab61a12856b6eb2f731824c79522d066daf66",AuthorityPayloadHashV1.Compute(GraphParticipantReservationPayloadRegistrationsV2.ReservationFact.SchemaToken,GraphParticipantReservationPayloadRegistrationsV2.ReservationFact.Schema,factOuter).ToString().Replace("sha256:",string.Empty,StringComparison.Ordinal));
        var ledgerDiscriminators=new ushort[]{43,44};Assert.Equal(ledgerDiscriminators,new ushort[]{GraphParticipantReservationPayloadRegistrationsV2.ReservationCommandDiscriminator,GraphParticipantReservationPayloadRegistrationsV2.ReservationFactDiscriminator});
        static string SchemaTokenHex(AuthorityPayloadRegistrationV1 registration){var token=System.Text.Encoding.ASCII.GetBytes(registration.SchemaToken.ToString());var bytes=new byte[token.Length+5];token.CopyTo(bytes,0);bytes[token.Length+2]=2;return Convert.ToHexString(bytes).ToLowerInvariant();}
        var commandSchemaTokenHex="6870642e617574686f726974792d7061796c6f61642d67726170682d7061727469636970616e742d7265736572766174696f6e2d636f6d6d616e642e76320000020000";var factSchemaTokenHex="6870642e617574686f726974792d7061796c6f61642d67726170682d7061727469636970616e742d7265736572766174696f6e2d666163742e76320000020000";
        Assert.Equal(commandSchemaTokenHex,Convert.ToHexString(Convert.FromHexString(SchemaTokenHex(GraphParticipantReservationPayloadRegistrationsV2.ReservationCommand))).ToLowerInvariant());
        Assert.Equal(factSchemaTokenHex,Convert.ToHexString(Convert.FromHexString(SchemaTokenHex(GraphParticipantReservationPayloadRegistrationsV2.ReservationFact))).ToLowerInvariant());
        Assert.True(GraphParticipantReservationCodecsV2.TryDecodeReservationCommand(commandOuter,out var c));Assert.Equal(commandOuter,GraphParticipantReservationCodecsV2.Encode(c!));
        Assert.True(GraphParticipantReservationCodecsV2.TryDecodeReservationFact(factOuter,out var f));Assert.Equal(factOuter,GraphParticipantReservationCodecsV2.Encode(f!));
    }

