    [Fact]
    public void MutationVectorsArePairwiseDistinct()
    {
        var mutations=new byte[][]{ApplyCanonicalMutation("outer-map-arity"),ApplyCanonicalMutation("map-key-order"),ApplyCanonicalMutation("major-type"),ApplyCanonicalMutation("truncate-final-byte"),ApplyCanonicalMutation("append-trailing-byte"),ApplyCanonicalMutation("noncanonical-integer"),ApplyCanonicalMutation("opaque-body-16385"),ApplyCanonicalMutation("swap-command-fact-body"),ApplyCanonicalMutation("command.outer.1.session"),ApplyCanonicalMutation("command.outer.2.expected-authority"),ApplyCanonicalMutation("command.outer.3.body"),ApplyCanonicalMutation("command.body.1.operation-id"),ApplyCanonicalMutation("command.body.2.expected-reservation-fact"),ApplyCanonicalMutation("command.body.3.runtime-generation"),ApplyCanonicalMutation("command.body.4.graph-generation"),ApplyCanonicalMutation("command.body.5.participant-plan-fingerprint"),ApplyCanonicalMutation("command.body.6.allocation-carrier-fingerprint"),ApplyCanonicalMutation("command.body.7.participant-factory-key"),ApplyCanonicalMutation("command.body.8.ordered-topology-node-keys"),ApplyCanonicalMutation("command.body.9.observed-at"),ApplyCanonicalMutation("fact.outer.1.session"),ApplyCanonicalMutation("fact.outer.2.expected-authority"),ApplyCanonicalMutation("fact.outer.3.body"),ApplyCanonicalMutation("fact.body.1.operation-id"),ApplyCanonicalMutation("fact.body.2.command-position"),ApplyCanonicalMutation("fact.body.3.actual-predecessor"),ApplyCanonicalMutation("fact.body.4.outcome"),ApplyCanonicalMutation("fact.body.5.runtime-generation"),ApplyCanonicalMutation("fact.body.6.graph-generation"),ApplyCanonicalMutation("fact.body.7.participant-plan-fingerprint"),ApplyCanonicalMutation("fact.body.8.allocation-carrier-fingerprint"),ApplyCanonicalMutation("fact.body.9.reservation"),ApplyCanonicalMutation("fact.body.10.safe-code"),ApplyCanonicalMutation("fact.body.11.observed-at")};
        var mutatedDigests=mutations.Select(static value=>Convert.ToHexString(SHA256.HashData(value))).ToArray();
        Assert.Equal(34,mutatedDigests.Distinct(StringComparer.Ordinal).Count());
    }

