        var(session,_)=Authority();var commandFactIdPreimage=Convert.FromHexString("6870642d73312d67726170682d7061727469636970616e742d7265736572766174696f6e2d636f6d6d616e642d666163742d69642d763200010000001003030303030303030303030303030303020000001001010101010101010101010101010101");var resultFactIdPreimage=Convert.FromHexString("6870642d73312d67726170682d7061727469636970616e742d7265736572766174696f6e2d726573756c742d666163742d69642d76320001000000100303030303030303030303030303030302000000080000000000000001");var commandFactIdDigest=Convert.ToHexString(SHA256.HashData(commandFactIdPreimage)).ToLowerInvariant();var resultFactIdDigest=Convert.ToHexString(SHA256.HashData(resultFactIdPreimage)).ToLowerInvariant();Assert.Equal("f573792bf3b2ad4a0705be83d89d2f06ed7ebec7fb29e8986be53ecd69916d10",commandFactIdDigest);Assert.Equal("d308e8d171b76c50f20f0eb272a07a70e564a5bec64e767f12b5bb1f22f6a041",resultFactIdDigest);Assert.Equal("fct:7NEDWJQWXJNN50E1DYGFC9TBR6",GraphParticipantReservationFactIdsV2.ReservationCommand(session,Operation()).ToString());Assert.Equal("fct:6K13MD2WDQDH8F43REP9SA0YKG",GraphParticipantReservationFactIdsV2.ReservationFact(Position(1)).ToString());Assert.NotEqual(GraphParticipantBindingFactIdsV1.ReservationCommand(session,Operation()),GraphParticipantReservationFactIdsV2.ReservationCommand(session,Operation()));var repaired=GraphParticipantReservationFactIdsV2.RepairZero(new byte[32]);Span<byte> repairedBytes=stackalloc byte[16];Assert.True(repaired.TryWriteBytes(repairedBytes));Assert.Equal("00000000000000000000000000000001",Convert.ToHexString(repairedBytes));
