    private static byte[] RewriteCbor(byte[] source,string path,string operation)
    {
        if(operation=="set-map-arity"){var result=source.ToArray();result[0]=0xa2;return result;}
        if(operation=="replace-major-type"){var result=source.ToArray();result[0]=0x83;return result;}
        if(operation=="widen-integer"){var result=new byte[source.Length+1];result[0]=source[0];result[1]=0x18;result[2]=source[1];source.AsSpan(2).CopyTo(result.AsSpan(3));return result;}
        var reader=new CborReader(source,CborConformanceMode.Lax);var count=reader.ReadStartMap()??throw new InvalidOperationException();var fields=new List<(ulong Key,byte[] Value)>(count);for(var i=0;i<count;i++){var key=reader.ReadUInt64();fields.Add((key,reader.ReadEncodedValue().ToArray()));}reader.ReadEndMap();
        if(operation=="reverse-key-order")fields.Reverse();
        else if(operation=="set-body-length-16385"){var w=new CborWriter(CborConformanceMode.Ctap2Canonical);w.WriteByteString(new byte[16385]);fields[fields.FindIndex(x=>x.Key==3)]=(3,w.Encode());}
        else
        {
            var marker=path.LastIndexOf('.');var fieldText=marker<0?string.Empty:path[(path.LastIndexOf('.',marker-1)+1)..marker];
            if(!ulong.TryParse(fieldText,out var field))field=1;
            var index=fields.FindIndex(x=>x.Key==field);if(index<0)index=0;var replacement=new CborWriter(CborConformanceMode.Ctap2Canonical);if(path.EndsWith("outer.3.body",StringComparison.Ordinal))replacement.WriteTextString(path);else replacement.WriteByteString(System.Text.Encoding.ASCII.GetBytes(path));fields[index]=(fields[index].Key,replacement.Encode());
        }
        var writer=new CborWriter(CborConformanceMode.Lax);writer.WriteStartMap(fields.Count);foreach(var field in fields){writer.WriteUInt64(field.Key);writer.WriteEncodedValue(field.Value);}writer.WriteEndMap();return writer.Encode();
    }
